(27, 'ClbBRDC6Z56Zasl5vefsRlW675CmkL6buggVfdAHLFwhW0lo5lScreenshot (22).png', '#', '/example/p___shoe_store', 'Ecommerce shoe store', 'html, css, bootstrap icons', 'mdsazzad0002@gmail.com', 'Ready to start an e-commerce store for you?', '2023-07-04 19:37:46', 'E-commerce'),
(28, 'hCVhLP95g4j54MsbD5G1XlmLgZeSw0Gb0R6sR7e4UakbPFfRllScreenshot (23).png', '#', '/example/p___ttcm_acme_deasing', 'portfolio of developer', 'html, css, bootstrap icons', 'mdsazzad0002@gmail.com', 'Indulge your senses with our enticing e-commerce food gallery. Discover a delectable array of culinary delights, from gourmet treats to comforting classics, all elegantly showcased for a mouthwatering online shopping experience. Elevate your gastronomic journey today.', '2023-07-04 19:41:57', 'portfolio'),
(29, '5gCKBGsKPW2jKtZxq3kf2rcom75qtFN2zUmff3XuR2i32kASjJScreenshot (24).png', '#', '/example/p___food_website', 'E-commerce food gallery', 'html css js', 'mdsazzad0002@gmail.com', 'this template best of your business', '2023-07-06 02:44:36', 'E-commerce'),
(31, 'r8NEIDjUCR2FTI7GnEIQFU6MURe7m3S82JiPg43njSY7XspWSmScreenshot (27).png', '#', '/example/p___dev_profile', 'Developer Profile', 'html, css only', 'mdsazzad0002@gmail.com', 'This project used only html and css.', '2023-07-15 17:43:07', 'portfolio'),
(32, 'j9I6cVajnYryE8QDNW7oPp5IOnjJkf0p3XrVxzUKp7uzmMo7ksScreenshot (28).png', '#', '/example/p___magazee', 'Mazee', 'only html css', 'mdsazzad0002@gmail.com', '', '2023-07-16 22:26:10', 'magazine'),
(33, 'zpgQJqg6Xn8fDI1bA0CDTESDswlfy61UXAiFMsTIrBl2YXZ8JOScreenshot (29).png', '#', '/example/p___youtube_video_creator', 'youtube video creator', 'html css', 'mdsazzad0002@gmail.com', 'this project used only html and css', '2023-07-18 03:46:07', 'servics'),
(34, '14XZV1OujaxTNAJh4sgg3ajX1CHTRdhkPp3l0ma76TfnneHJVAScreenshot (30).png', '#', '/example/p___e_dnk', 'E-commerce DNK', 'html css js etc.', 'mdsazzad0002@gmail.com', 'Explore DNK, your ultimate e-commerce destination. Discover a curated selection of products, shop securely, and enjoy swift deliveries. Elevate your online shopping with DNK\'s seamless experience.', '2023-07-18 20:35:44', 'E-commerce'),
(35, 'vaiCx4hAIxQYpg2nou4n0JZ3FOYXJXnqi82sOY3bu8kcvREktgScreenshot (31).png', '#', '/example/p___claning servics', 'Cleaning Services', 'html css js etc.', 'mdsazzad0002@gmail.com', 'Transform your space with our professional cleaning services. Our expert team ensures a spotless environment, offering tailored solutions for homes and businesses. Experience cleanliness redefined.', '2023-07-20 03:00:45', 'servics'),
(36, 'si3UNRcsheEQ5lHIrWY3FGOgoNFdZUho6s0VKMICRbwcBEp4ImScreenshot (33).png', '#', '/example/p___online_store', 'Online Store', 'html, css, bootstrap, slider sclic js', 'mdsazzad0002@gmail.com', 'Discover a vast online store where you can explore and shop for a diverse range of products. Browse categories, find deals, and enjoy seamless checkout for a convenient shopping experience. Elevate your shopping journey with our user-friendly platform.', '2023-07-21 23:01:20', 'E-commerce'),
(37, 'wrLfiI9YEUO9Rxdrc56WAS5TcLrO6TsdKlmEonx2n8QR1mMPnDScreenshot (36).png', '#', '/example/p___app_landing_page', 'App Landing Page', 'html, css, js swiper js etc', 'mdsazzad0002@gmail.com', 'Welcome back! Log in to access your account.!\r\nSecure your data. Log in now.\r\nUnlock the app\'s features. Sign in.', '2023-08-14 00:56:39', 'app-land'),
(38, 'lnMdB2ifWxXPIbNkqQJtM3wvQgmrkLtu8o5zyiOSRlwvfRyhi7screencapture-ttcm-pw-example1-book-2023-08-22-19_28_53.png', '#', '/example/p___book', 'Bay A Book ', 'html, css, js( swiper, count) ', 'mdsazzad0002@gmail.com', '---', '2023-08-16 08:15:41', 'portfolio'),
(39, 'zbajLZe9G2svyHRADbBt4sH7WaWL8Ax1L11dXr9ZcZqNRA1PbKScreenshot (45).png', '#', '/example/p___doctor', 'Donatist, doctor is first choose', 'html, css, bootstrap icon, js', 'mdsazzad0002@gmail.com', 'The world has gone digital and having a website has become a crucial aspect for any business.\r\n\r\nThe same applies to dental practices. A website not only serves as a platform for potential patients to learn about your services but also helps to establish your practice as a credible and trustworthy source for dental care.\r\n\r\nIn this digital era, having a strong online presence is essential for dentists to reach a wider audience and keep up with the competition.', '2023-08-21 02:46:06', 'doctor'),
(42, 'MaG3TtOUM8L20qha6O64D9vfwtRwdf8TsqKA2plctrpZDWhgQSScreenshot (51).png', '#', '/example/p___medical', 'Medical & Pharmacist Doctor Booking Website', 'html, css, js, bootstrap etc', 'mdsazzad0002@gmail.com', 'Provide Better Patient Care. With an online booking system, patients can make appointments at times that suit them. Plus, due to last-minute cancellations, clients may even be able to find same-day appointments. This way, clients don\'t need to keep sharing the same information each time they visit.', '2023-09-10 12:39:37', 'doctor'),
(43, 'vrE8M9mOGI9SOkOnt1aFqkWs89B08owAqCAShDQ3o7ijCkbm4XScreenshot (52).png', '#', '/example/p___displaywebpage', 'how to work your Website', 'html, css, js, bootstrap etc', 'mdsazzad0002@gmail.com', 'The process of presenting your website in a more personal way increases the reach of your website. Hence the need for publicity and an attractive website reduces its responsibility to a great extent.', '2023-09-10 12:51:25', 'app-land'),
(44, 'xqvpeWytJJssL1kZZikvXNcHNVFVZG17M4hX9pdpODYQgYzVJAScreenshot (53).png', '#', '/example/p___book_store', 'Book Publisher', 'html, css, js, bootstrap etc', 'mdsazzad0002@gmail.com', 'Are you an author but looking for an easy way to publish and sell your published book? But not getting Easy solution for you is online platform form through which you can easily find your buyer. A study found. If facebook promotion is done along with web site then the business will increase at double rate.', '2023-09-10 13:20:33', 'portfolio'),
(45, 'XdlMf9G8LnItUhKHfhFp5lp00yqafUE3Rj0EtN0AkvATd7YcfDScreenshot (54).png', '#', '/example/p___e_School', 'E-School', 'html, css, js, bootstrap etc', 'mdsazzad0002@gmail.com', 'e-School is an on-premise and cloud-based solution that helps educational institutions handle accounting, class management, scheduling and other administrative processes on a centralized platform. Professionals can track the daily attendance of students and teachers, approve leave requests and generate monthly reports.', '2023-09-10 13:37:24', 'education'),
(46, 'f1KY7hGM0mU0re49L3coB6o6DORwE2ebpRlGdX2sF98aDUCez5Screenshot (55).png', '#', '/example/p___protfilio_video', 'Creative Technologist', 'html, css, js, bootstrap etc', 'mdsazzad0002@gmail.com', 'Having a website allows you to market your business online, 24/7. There are several ways to market your website and business online. Executing digital marketing strategies will help you reach your target audience. You will be able to connect with your customers, and increase conversion.', '2023-09-11 01:56:51', 'portfolio'),
(49, 'K96rEr2GGuB3WLhTJpHjYy0z0VkyourWAo8Mwh6MfVsFmra4iTScreenshot_1.png', '#', '/example/p____northernfertilizer', 'Nordan Fartilizer', 'html, css, js, bootstrap etc', 'mdsazzad0002@gmail.com', 'dsadsad', '2023-11-23 07:13:48', 'servics'),
(50, 'HYSmwww6LSFSytpAElGkgqNjHU0ISKCBWmIAj3YTwk81Xi1bqmScreenshot (59).png', '#', '/example/p____realstate', 'Real State', 'html, css, js, bootstrap etc', 'mdsazzad0002@gmail.com', '', '2023-11-23 07:30:22', 'servics'),
(51, 'plXqg5BTvPMQUr6KTSuT3fXTl7Llg2HvNlyRQWAwloFwAP1gcvScreenshot (60).png', '#', '/example/p___ebook', 'PDF Shop', 'html, css, js, bootstrap etc', 'mdsazzad0002@gmail.com', '', '2023-11-23 07:55:38', 'servics'),
(52, 'JdpuzcXp5umbrOhOzNRvCIMUwx5cIfQNqzJeL4JYYl1dI80xiDScreenshot_5.png', '#', '/example/p___d_tech', 'D TECH', 'html, css, swiper slider', 'mdsazzad0002@gmail.com', '---', '2024-01-11 23:43:54', 'portfolio'),
